mapper.select:
select nurse_plan.*, nurse.name as nurseName, department.name as departmentName, department.id as departmentId, hospital.hospital_name as hospitalName
from nurse_plan
left join nurse on nurse_plan.nurse_id = nurse.id
left join department on nurse.department_id = department.id
left join hospital on nurse_plan.hospital_id = hospital.id

     and id= #{id}
     and nurse_plan.date = #{date}
     and nurse_plan.nurse_id = #{nurseId}
     and nurse_plan.hospital_id = #{hospitalId}

order by id desc
